import{_ as r,l as o,o as e,c as s,v as l,p as n,x as t,d as E,i as h,S as p}from"./chunks/framework.InCnrqk-.js";const b=JSON.parse('{"title":"EUV 吸收与模糊","description":"","frontmatter":{"title":"EUV 吸收与模糊","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/euv-absorption-blur.md","filePath":"litho/euv-absorption-blur.md","lastUpdated":1789023840000}'),d={name:"litho/euv-absorption-blur.md"};function A(c,a,u,B,m,D){const i=o("Mermaid");return e(),s("div",null,[a[1]||(a[1]=l('<h1 id="euv-吸收与模糊" tabindex="-1">EUV 吸收与模糊 <a class="header-anchor" href="#euv-吸收与模糊" aria-label="Permalink to &quot;EUV 吸收与模糊&quot;">​</a></h1><div class="epigraph"><p>92 eV 的光子在胶里打出二次电子；电子射程与酸扩散一起给潜像加核，光学 NILS 再陡也要先过这层模糊。</p><footer>—— 据 Naulleau 对 EUV 二次电子模糊、De Bisschop 对随机与模糊的公开论述</footer></div><p><a href="/litho/actinic-blank-inspect">上一课</a>把掩模空白的相位缺陷在 13.5 nm 上找出来。缺口是：光子到达硅片之后并不是在几何边缘上「点亮即停」——吸收事件产生二次电子，CAR 里酸还要走一段，潜像等于空中像卷积一个纳米量级的核。本课钉 EUV 吸收与模糊。光学课序里的掩模与胶接口到此；<a href="/litho/asml-nxe">NXE</a> 把整机场几何收成量产平台。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>EUV 光子能量约 92 eV，是 ArF 的十几倍。一次吸收能打出级联二次电子，电子在凝聚态里走纳米量级才把能量交给 PAG 或金属团簇。Naulleau 等把这层叫做二次电子模糊（secondary electron blur）：它不按 \\(\\lambda/\\mathrm{NA}\\) 缩放，也不按 \\(\\lambda/\\mathrm{NA}^2\\) 的焦深缩放。空中像再陡，卷积之后边缘变钝，NILS 下降。</p><p>CAR 还要叠酸扩散：PEB 里酸的 \\(\\ell\\) 已在<a href="/litho/acid-diffusion-lwr">酸扩散</a>课写过，EUV 半节距与 \\(\\ell\\)、电子射程叠在同一尺度。De Bisschop 把模糊、光子散粒和化学离散放在同一张随机账上：模糊既降分辨率，也改局部有效体积，从而改泊松 \\(N\\)。只加 NA 不改核，墙会前移。</p><h3 id="光学模糊与化学核不是一个旋钮" tabindex="-1">光学模糊与化学核不是一个旋钮 <a class="header-anchor" href="#光学模糊与化学核不是一个旋钮" aria-label="Permalink to &quot;光学模糊与化学核不是一个旋钮&quot;">​</a></h3><p>离焦、像差、flare 改空中像。二次电子与酸改记录介质的响应。调焦补不了电子射程；降 PEB 补不了镜头 flare。RLS 三角在这里具体化：要灵敏度就倾向更大化学增益、往往更大 \\(\\ell\\)；要分辨率就压核、通常加剂量。金属氧化物胶减小酸程，核更接近电子与团簇离散，换的是另一套缺陷学习曲线。</p><p><span class="marginnote">不要把「EUV 模糊」写成某一个发明的纳米常数。公开论述给出的是纳米量级二次电子射程与可调的酸扩散，随胶配方变。本课钉机制，不写未校准的全球 \\(\\ell\\)。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>紧凑抗蚀剂模型把吸收写成剂量 → 酸/事件密度，再卷积电子核与酸核，然后进显影。OPC 用的是这颗等效核，不是分子动力学。量测上，通过焦点的 CD、LER 频谱和缺失孔对剂量的曲线，用来把核与光子噪声拆开：核主要砍中高频、降 NILS；泊松在孔面积缩小时主导缺陷尾。</p><p>控制：减胶厚（少纵向吸收梯度、少电子从衬底回弹的复杂路径）、调 PAG/淬灭剂、换高吸收胶让同样 \\(D\\) 下事件更多从而可牺牲一点增益。High-NA 焦深更薄，胶厚预算更紧，核与厚度一起被削——那是后课胶厚预算的入口，本课只要求模型声明电子项。</p><h3 id="与随机效应课的分工" tabindex="-1">与随机效应课的分工 <a class="header-anchor" href="#与随机效应课的分工" aria-label="Permalink to &quot;与随机效应课的分工&quot;">​</a></h3><p><a href="/litho/euv-stochastics">随机效应</a>主钉光子计数与缺陷悬崖。本课主钉平均场里的空间核：同样平均 \\(D\\)，核宽了则边缘缓、桥接窗变窄。De Bisschop 的公开图把 LCDU 同时写成对比、模糊和 \\(N\\) 的函数。后课机台剂量只提供 \\(D\\)；核在胶与 PEB 里。</p>',14)),(e(),n(p,null,{default:t(()=>[h(i,{id:"mermaid-40",class:"mermaid",graph:"flowchart%20TD%0A%20%20AI%5B%22%E7%A9%BA%E4%B8%AD%E5%83%8F%22%5D%20--%3E%20ABS%5B%2292%20eV%20%E5%90%B8%E6%94%B6%22%5D%0A%20%20ABS%20--%3E%20SE%5B%22%E4%BA%8C%E6%AC%A1%E7%94%B5%E5%AD%90%E6%A0%B8%22%5D%0A%20%20SE%20--%3E%20ACID%5B%22%E9%85%B8%E6%89%A9%E6%95%A3%E6%A0%B8%20CAR%22%5D%0A%20%20SE%20--%3E%20CL%5B%22%E5%9B%A2%E7%B0%87%E4%BA%8B%E4%BB%B6%20%E9%87%91%E5%B1%9E%E8%83%B6%22%5D%0A%20%20ACID%20--%3E%20LAT%5B%22%E6%BD%9C%E5%83%8F%22%5D%0A%20%20CL%20--%3E%20LAT%0A%20%20LAT%20--%3E%20DEV%5B%22%E6%98%BE%E5%BD%B1%20%2F%20LER%20%2F%20%E7%BC%BA%E5%AD%94%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=l('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>吸收截面决定光子在哪一层被吃掉。电子级联把能量涂开几个纳米，PAG 电离或激发的位置不等于光子吸收点。酸催化再把事件半径放大。总模糊近似若干核的卷积，密图形的 ILS 先被吃掉。衬底与底层的二次电子产额会加一层「从下面打上来」的底座，所以底层不只是黏附，也是模糊与反射的接口。</p><p>掩模吸收体边缘的电磁已经三维；胶核再涂一次，MEEF 与桥接对核宽敏感。光化检验保证掩模上没有致命坑，不保证胶能分辨光学上刚刚分开的两条线。分辨率合同是光学截止乘记录核，不是瑞利式单独成立。</p><p><span class="marginnote">Naulleau 的实验与仿真强调：即使理想光学，电子模糊也给 EUV 一条底线。De Bisschop 强调：这条底线与随机缺陷必须放在同一工艺窗口里读，不能只报平均 CD。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把某篇 SPIE 的 2 nm 或 5 nm 核写成所有 EUV 层的预算。也不重讲 PAG 化学循环。后课默认：说到 EUV 分辨率，除 \\(k_1\\lambda/\\mathrm{NA}\\) 外要问吸收模糊核。机台课序从 NXE 场与 NA 合同开始，胶核当作已存在的记录限制。</p><p>出处：Naulleau 对 EUV 二次电子与抗蚀剂模糊；De Bisschop 对随机、LCDU 与模糊；Mack 对 CAR 扩散。不发明 arXiv 编号或未公开的核宽度表。</p><p><span class="marginnote">加剂量可以提高 \\(N\\)、改善随机尾，但平均场核宽度主要随电子与酸，不随剂量线性消失。用剂量「洗掉模糊」会误导 TPT 会计。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>92 eV 吸收产生纳米量级二次电子模糊，CAR 再叠酸扩散。</li><li>潜像 = 空中像 ∗ 核；密图形 NILS 先被核吃掉。</li><li>模糊与光子散粒一起进 LCDU/缺孔，但旋钮不同。</li><li>紧凑 OPC 必须声明电子项，不能只用 DUV 酸核。</li><li>掩模光化检验不替代胶核；下一课序进入 NXE 整机。</li><li>出处：Naulleau；De Bisschop；Bakshi / Mack 对 EUV 胶模糊。</li></ul>',10))])}const f=r(d,[["render",A]]);export{b as __pageData,f as default};
